"""Cuaderno del estudiante, 2.º medio Lengua y Literatura, OA 17 (frases nominales complejas y correferencia) y OA 18 (ortografía y puntuación).

Todos los textos, oraciones y fichas son originales e inventados («de ejemplo»); cada ejercicio trae escritos los textos que necesita.
Nota: los títulos de las clases del repositorio ordenan cada OA en etapas de proceso (reconocer propósito, reunir insumos, planificar,
escribir, revisar, editar); este cuaderno las sigue y reparte entre ellas los contenidos del OA oficial.
Los ayudantes `E`, `L`, `task`, `Q` se copian aquí para que el módulo sea independiente.
"""
from __future__ import annotations

from student_lessons import arith, ex, register

OA17 = "LE2M OA 17"
OA18 = "LE2M OA 18"
E = ex

MAT = "Este cuaderno, lápiz y los textos y datos escritos en cada ejercicio. No necesitas libros especiales ni internet."


def task(statement, example, criteria, evidence, errors, feedback):
    return {"statement": statement, "example": example, "criteria": criteria, "evidence": evidence, "errors": errors, "feedback": feedback}


def L(oa, n, use, prior, explain, vocab, worked, mistakes, tiers, ctx, sc, open_task, reinforce, extend, materials=MAT):
    register(
        oa, n, materials=materials, use=use, prior=prior, explain=explain, vocab=vocab,
        worked=[{"title": t, "problem": p, "steps": s, "answer": a} for t, p, s, a in worked],
        mistakes=[{"wrong": w, "why": y, "fix": f} for w, y, f in mistakes],
        tiers=dict(zip(("recovery", "understand", "apply", "reason", "challenge"), tiers)),
        context=ctx, selfcheck=sc, open_task=task(*open_task), reinforce=reinforce, extend=extend,
    )


def Q(stem, opts, k, why):
    """Pregunta cerrada con opciones «A) … B) … C) …» al final; `k` es el índice de la correcta."""
    letters = "ABCD"
    q = stem + " " + " ".join(f"{letters[i]}) {o}" for i, o in enumerate(opts))
    return E(q, f"{letters[k]}) {opts[k]}", why)


